function queryLiteral(value) {
  if (!object(value)) return 'never';
  return Object.keys(value).length ? '{ ' + Object.keys(value).map(key => `readonly ${quote(key)}: QueryValue;`).join(' ') + ' }' :
    'Readonly<Record<string, never>>';
